// Get Gemini response
let response = $json.content.parts[0].text;

// Remove markdown if present
response = response
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

const parsed = JSON.parse(response);

// Convert NEW Gemini format into the OLD workflow format

const activities = [];

parsed.days.forEach(day => {
  day.activities.forEach((activity, index) => {
    activities.push({
      day_number: day.day,
      activity_order: index + 1,
      start_time: activity.time,
      end_time: "",
      activity_name: activity.activity_name,
      description: activity.description,
      category: activity.category,
      location: activity.location,
      latitude: "",
      longitude: "",
      estimated_cost: activity.estimated_cost,
      indoor: activity.indoor,
      status: "Planned",
      notes: ""
    });
  });
});

return [
  {
    json: {
      trip: {
        trip_name: parsed.trip_title,
        destination: $('Code in JavaScript4').item.json.destination,
        country: "",
        start_date: $('Code in JavaScript3').item.json.startDate,
        end_date: $('Code in JavaScript3').item.json.endDate,
        number_of_days: parsed.days.length,
        budget: $('Code in JavaScript3').item.json.budget,
        currency: $('Code in JavaScript3').item.json.currency,
        travelers: $('Code in JavaScript3').item.json.people,
        trip_style: $('Code in JavaScript3').item.json.style,
        status: parsed.budget_status
      },
      activities
    }
  }
];

const footer = `

━━━━━━━━━━━━━━

🏠 Type *home* to return to the main menu.`;

const trips = $('Get Trips Data').all();
const activities = $('Gets Activities Data').all();

const latestTrip = trips[trips.length - 1].json;

const tripName = latestTrip["Trip Name"];
const destination = latestTrip["Destination"];
const startDate = latestTrip["Start Date"];
const endDate = latestTrip["End Date"];
const travelers = latestTrip["Travelers"];
const budget = latestTrip["Budget"];
const currency = latestTrip["Currency"];

// Filter only this trip's activities
const tripActivities = activities.filter(
    item => item.json["Trip Name"] === tripName
);

// Group activities by day
const days = {};

tripActivities.forEach(item => {
    const day = item.json["Day Number"];

    if (!days[day]) {
        days[day] = [];
    }

    days[day].push(item.json["Activity Name"]);
});

// Total days
const totalDays = Object.keys(days).length;

// Build message
let message = `🏝 *${tripName}*\n\n`;

message += `📍 ${destination}\n`;
message += `📅 ${startDate} → ${endDate} (${totalDays} Days)\n`;
message += `👥 ${travelers} Traveler${travelers > 1 ? "s" : ""}\n`;
message += `💰 ${budget} ${currency}\n`;

message += `\n━━━━━━━━━━━━━━\n\n`;

Object.keys(days)
    .sort((a, b) => a - b)
    .forEach(day => {

        message += `🌅 *DAY ${day}*\n`;

       const previewLimit = 4; // Show only the first 4 activities

days[day]
    .slice(0, previewLimit)
    .forEach(activity => {
        message += `• ${activity}\n`;
    });

if (days[day].length > previewLimit) {
    message += `• ...and ${days[day].length - previewLimit} more\n`;
}

        message += `\n`;
    });

message += `━━━━━━━━━━━━━━\n\n`;

message += `📖 View detailed schedule:\n`;

Object.keys(days)
    .sort((a, b) => a - b)
    .forEach(day => {
        message += `• DAY ${day}\n`;
    });

message += footer;


return [{
    json: {
        message
    }
}];

let response = $json.content.parts[0].text;

// Remove markdown if Gemini wraps JSON
response = response
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

const parsed = JSON.parse(response);

return [
  {
    json: {
      origin: parsed.origin,
      destination: parsed.destination,
      transportMode: parsed.transportMode,
      startDate: parsed.startDate,
      endDate: parsed.endDate,
      people: parsed.people,
      budget: parsed.budget,
      currency: parsed.currency,
      style: parsed.style,

      hasOrigin: !!parsed.origin,
      hasDestination: !!parsed.destination,
      hasTransportMode: !!parsed.transportMode,
      hasStartDate: !!parsed.startDate,
      hasEndDate: !!parsed.endDate,
      hasPeople: parsed.people > 0,
      hasBudget: parsed.budget > 0,

      isComplete: parsed.isComplete,
      missingFields: parsed.missingFields
    }
  }
];

const footer = `

━━━━━━━━━━━━━━

🏠 Need anything else?

Type "home" to return to the main menu.`;

const activities = $input.all();

if (activities.length === 0) {
  return [{
    json: {
      message: "No itinerary found." + footer
    }
  }];
}

// Sort by activity order
activities.sort((a, b) =>
  Number(a.json["Activity Order"]) -
  Number(b.json["Activity Order"])
);

const day = activities[0].json["Day Number"];

let output = `📅 *DAY ${day}*\n\n`;

activities.forEach(a => {
  output +=
`🕒 ${a.json["Start Time"]} - ${a.json["End Time"]}
📍 *${a.json["Activity Name"]}*

${a.json["Description"]}

`;
});

output += footer;

return [{
  json: {
    message: output
  }
}];

const places = $json.places || [];

// Get destination from parser
const destination = $('Sufficient Data Available or not')
  .item
  .json
  .destination
  .replace(/\b\w/g, c => c.toUpperCase());

// Google Places API Key
const apiKey = "AIzaSyCBRnElygDMtLsWHOUwWHQCgEUOr0qJtMQ";

// Allowed attraction types
const allowedTypes = [
  "tourist_attraction",
  "museum",
  "park",
  "national_park",
  "zoo",
  "beach",
  "church",
  "hindu_temple",
  "mosque",
  "synagogue",
  "place_of_worship",
  "historical_landmark",
  "monument",
  "fortress",
  "castle",
  "scenic_lookout",
  "botanical_garden"
];

// Filter useful attractions with photos
// Filter useful attractions with photos
const filtered = places
  .filter(place =>
    allowedTypes.includes(place.primaryType) &&
    place.photos &&
    place.photos.length > 0 &&
    place.photos[0]?.name
  )
  // Sort primarily by popularity (review count),
  // then by rating if review counts are equal.
  .sort((a, b) => {
    const reviewDifference =
      (b.userRatingCount || 0) - (a.userRatingCount || 0);

    if (reviewDifference !== 0) {
      return reviewDifference;
    }

    return (b.rating || 0) - (a.rating || 0);
  });

// Top 5 attractions
const attractions = filtered.slice(0, 5).map(place => ({
  name: place.displayName?.text || "Unknown",
  rating: place.rating || "N/A",
  userRatingCount: place.userRatingCount || 0,
  type: place.primaryType || "",
  address: place.formattedAddress || "",
  maps: place.googleMapsUri || "",
  photoName: place.photos?.[0]?.name || ""
}));

// Rich attraction list for Gemini
// Rich attraction list for Gemini
const attractionList = attractions
  .map((a, i) => `
#${i + 1}

${a.name}

👥 Reviews: ${a.userRatingCount.toLocaleString()}

⭐ Rating: ${a.rating}

🏷️ Category: ${a.type
  .replace(/_/g, " ")
  .replace(/\b\w/g, c => c.toUpperCase())}

📍 Address: ${a.address}
`)
  .join("\n");

// Telegram media array
const media = attractions.map((a, index) => ({
  type: "photo",
  media: `https://places.googleapis.com/v1/${a.photoName}/media?maxWidthPx=1200&key=${apiKey}`,
  ...(index === 0
    ? {
        caption:
`📸 Top Attractions in ${destination}

${attractions
  .map(x => `📍 ${x.name} ⭐ ${x.rating}`)
  .join("\n")}

Swipe to explore ➜`
      }
    : {})
}));


return [{
  json: {
    destination,
    attractions,
    attractionList,
    media,
    firstPhoto: media[0].media
  }
}];
